CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,referral_code VARCHAR(24) NULL UNIQUE,balance_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,password_changed_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallet_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,amount_cents BIGINT NOT NULL,balance_before_cents BIGINT UNSIGNED NOT NULL,balance_after_cents BIGINT UNSIGNED NOT NULL,type VARCHAR(32) NOT NULL,order_id BIGINT UNSIGNED NULL,payment_id BIGINT UNSIGNED NULL,admin_id BIGINT UNSIGNED NULL,reason VARCHAR(500) NOT NULL DEFAULT '',idempotency_key VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_wallet_idempotency(idempotency_key),KEY idx_wallet_user(user_id,id),KEY idx_wallet_order(order_id,payment_id),KEY idx_wallet_created_type(created_at,type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(100) NOT NULL DEFAULT '',role VARCHAR(30) NOT NULL DEFAULT 'admin',status VARCHAR(20) NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS account_platforms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT NOT NULL,product_type VARCHAR(20) NOT NULL DEFAULT 'vpn',account_platform VARCHAR(32) NULL,account_specification TEXT NULL,account_after_sales TEXT NULL,traffic VARCHAR(100) NULL,region VARCHAR(100) NULL,device_limit INT UNSIGNED NULL DEFAULT 1,duration_days INT UNSIGNED NULL,price_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_product_status_sort(status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,duration_days INT UNSIGNED NULL,price_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_product_plan_name(product_id,name),KEY idx_product_plan_status(product_id,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,product_plan_id BIGINT UNSIGNED NULL,product_name_snapshot VARCHAR(160) NOT NULL,plan_name_snapshot VARCHAR(100) NOT NULL DEFAULT '',product_description_snapshot TEXT NOT NULL,product_type_snapshot VARCHAR(20) NOT NULL DEFAULT 'vpn',account_platform_snapshot VARCHAR(32) NULL,account_platform_name_snapshot VARCHAR(100) NULL,account_specification_snapshot TEXT NULL,account_after_sales_snapshot TEXT NULL,traffic_snapshot VARCHAR(100) NULL,region_snapshot VARCHAR(100) NULL,device_limit_snapshot INT UNSIGNED NULL,duration_days_snapshot INT UNSIGNED NULL,unit_price_cents_snapshot BIGINT UNSIGNED NOT NULL,original_amount_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,discount_amount_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,promotion_code VARCHAR(100) NOT NULL DEFAULT '',total_amount_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending_payment',customer_note VARCHAR(500) NOT NULL DEFAULT '',payment_started_at DATETIME NULL,paid_payment_record_id BIGINT UNSIGNED NULL,refund_previous_status VARCHAR(30) NULL,cancelled_at DATETIME NULL,cancelled_by_type VARCHAR(20) NULL,cancelled_by_id BIGINT UNSIGNED NULL,cancel_reason VARCHAR(500) NOT NULL DEFAULT '',refund_requested_at DATETIME NULL,refund_processed_at DATETIME NULL,refund_reason VARCHAR(500) NOT NULL DEFAULT '',temporary_subscription_url VARCHAR(500) NOT NULL DEFAULT '',temporary_subscription_status VARCHAR(20) NOT NULL DEFAULT 'none',temporary_subscription_issued_at DATETIME NULL,temporary_subscription_revoked_at DATETIME NULL,created_at DATETIME NOT NULL,paid_at DATETIME NULL,delivered_at DATETIME NULL,updated_at DATETIME NOT NULL,KEY idx_order_user(user_id,created_at),KEY idx_order_status(status,created_at),KEY idx_order_plan(product_plan_id),KEY idx_order_promotion_code(promotion_code),UNIQUE KEY uk_order_paid_payment(paid_payment_record_id),KEY idx_order_paid_at(paid_at),KEY idx_order_refund_time(status,refund_processed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,method VARCHAR(40) NOT NULL DEFAULT 'manual',amount_cents BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',confirmed_by BIGINT UNSIGNED NULL,confirmed_at DATETIME NULL,gateway_trade_no VARCHAR(100) NOT NULL DEFAULT '',gateway_order_no VARCHAR(64) NOT NULL DEFAULT '',gateway_type VARCHAR(20) NOT NULL DEFAULT '',payment_url VARCHAR(1000) NOT NULL DEFAULT '',paid_at DATETIME NULL,notify_payload TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_payment_order(order_id),KEY idx_payment_order_status(order_id,status,id),KEY idx_payment_gateway_trade(gateway_trade_no),KEY idx_payment_paid_status(paid_at,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS delivery_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,action VARCHAR(20) NOT NULL,content_ciphertext MEDIUMTEXT NOT NULL,content_nonce VARBINARY(32) NOT NULL,content_tag VARBINARY(32) NOT NULL,content_preview VARCHAR(255) NOT NULL DEFAULT '',is_current TINYINT(1) NOT NULL DEFAULT 1,opened_at DATETIME NULL,expires_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_delivery_version(order_id,version_no),KEY idx_delivery_current(order_id,is_current)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_no VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,subject VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',version_no INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,closed_at DATETIME NULL,KEY idx_ticket_user(user_id,updated_at),KEY idx_ticket_status(status,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS feedback_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feedback_no VARCHAR(48) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(30) NOT NULL DEFAULT 'suggestion',subject VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reward_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,reward_transaction_id BIGINT UNSIGNED NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,admin_note VARCHAR(500) NOT NULL DEFAULT '',progress_status VARCHAR(24) NULL DEFAULT NULL,progress_updated_at DATETIME NULL DEFAULT NULL,progress_version INT UNSIGNED NOT NULL DEFAULT 0,submission_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_feedback_submission(user_id,submission_key),UNIQUE KEY uk_feedback_reward(user_id,reward_transaction_id),KEY idx_feedback_user(user_id,created_at),KEY idx_feedback_status(status,created_at),KEY idx_feedback_progress(progress_status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS feedback_progress_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,feedback_id BIGINT UNSIGNED NOT NULL,from_status VARCHAR(24) NULL,to_status VARCHAR(24) NOT NULL,public_note VARCHAR(1000) NOT NULL,actor_type VARCHAR(16) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,request_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_feedback_progress_request(feedback_id,actor_type,actor_id,request_key),KEY idx_feedback_progress_event(feedback_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(24) NOT NULL DEFAULT 'system',title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',starts_at DATETIME NOT NULL,ends_at DATETIME NULL,pinned TINYINT(1) NOT NULL DEFAULT 0,admin_id BIGINT UNSIGNED NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_announcement_visible(status,starts_at,ends_at),KEY idx_announcement_order(pinned,starts_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_operations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,actor_type VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,operation VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,result_json TEXT NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_ticket_operation_request(actor_type,actor_id,operation,request_key),KEY idx_ticket_operation_ticket(ticket_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,sender_type VARCHAR(20) NOT NULL,sender_user_id BIGINT UNSIGNED NULL,sender_admin_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL,KEY idx_message_ticket(ticket_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,target_type VARCHAR(40) NOT NULL,target_id BIGINT UNSIGNED NULL,details_json LONGTEXT NULL,created_at DATETIME NOT NULL,KEY idx_log_admin(admin_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,category VARCHAR(40) NOT NULL DEFAULT '使用教程',summary VARCHAR(500) NOT NULL DEFAULT '',content TEXT NOT NULL,cover_style VARCHAR(30) NOT NULL DEFAULT 'blue',status VARCHAR(20) NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_article_status_publish(status,published_at),KEY idx_article_updated(updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS download_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,app_name VARCHAR(80) NOT NULL,version VARCHAR(60) NOT NULL DEFAULT '',description VARCHAR(500) NOT NULL DEFAULT '',project_url VARCHAR(500) NOT NULL,platform VARCHAR(20) NOT NULL,filename VARCHAR(120) NOT NULL,source_url VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_download_resource(app_name,platform,filename),KEY idx_download_status_platform(status,platform,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,gateway_url VARCHAR(500) NOT NULL DEFAULT 'https://pae.fksqy.cn/',pid VARCHAR(40) NOT NULL DEFAULT '',md5_key_ciphertext MEDIUMTEXT NOT NULL,md5_key_nonce VARBINARY(32) NOT NULL,md5_key_tag VARBINARY(32) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,alipay_enabled TINYINT(1) NOT NULL DEFAULT 1,wechat_enabled TINYINT(1) NOT NULL DEFAULT 1,notify_base_url VARCHAR(500) NOT NULL DEFAULT '',updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(80) NOT NULL UNIQUE,setting_value VARCHAR(1000) NOT NULL DEFAULT '',setting_ciphertext MEDIUMTEXT NULL,setting_nonce VARBINARY(32) NULL,setting_tag VARBINARY(32) NULL,is_secret TINYINT(1) NOT NULL DEFAULT 0,updated_by BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notification_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,channel VARCHAR(30) NOT NULL,event_type VARCHAR(60) NOT NULL,dedupe_key VARCHAR(160) NOT NULL UNIQUE,payload_json LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',retry_count INT UNSIGNED NOT NULL DEFAULT 0,available_at DATETIME NOT NULL,locked_at DATETIME NULL,sent_at DATETIME NULL,last_error VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_outbox_status_available(status,available_at,id),KEY idx_outbox_event(event_type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,request_ip VARCHAR(45) NOT NULL DEFAULT '',created_at DATETIME NOT NULL,KEY idx_password_reset_user(user_id,created_at),KEY idx_password_reset_expiry(expires_at,used_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(40) NOT NULL,old_status VARCHAR(30) NULL,new_status VARCHAR(30) NULL,description VARCHAR(500) NOT NULL,actor_type VARCHAR(20) NOT NULL,actor_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,KEY idx_order_event(order_id,created_at),KEY idx_order_event_type(event_type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
