CREATE TABLE IF NOT EXISTS activity_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,activity_key VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,description VARCHAR(500) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'disabled',config_json LONGTEXT NOT NULL,start_at DATETIME NULL,end_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_activity_status_time(status,start_at,end_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lottery_prizes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,activity_id BIGINT UNSIGNED NOT NULL,prize_code VARCHAR(80) NOT NULL,name VARCHAR(160) NOT NULL,prize_type VARCHAR(30) NOT NULL DEFAULT 'coupon',value_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,min_amount_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,valid_days INT UNSIGNED NOT NULL DEFAULT 30,quantity INT NOT NULL DEFAULT -1,remaining_quantity INT NOT NULL DEFAULT -1,weight INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_lottery_prize_code(activity_id,prize_code),KEY idx_lottery_prize_status(activity_id,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
