CREATE TABLE IF NOT EXISTS withdrawal_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_no VARCHAR(64) NOT NULL UNIQUE,idempotency_key VARCHAR(100) NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,amount_cents BIGINT UNSIGNED NOT NULL,fee_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,net_amount_cents BIGINT UNSIGNED NOT NULL,channel VARCHAR(30) NOT NULL,account_name VARCHAR(120) NOT NULL DEFAULT '',account_no VARCHAR(190) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,paid_at DATETIME NULL,reject_reason VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_withdrawal_user_status(user_id,status,created_at),KEY idx_withdrawal_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS group_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_no VARCHAR(64) NOT NULL UNIQUE,activity_id BIGINT UNSIGNED NULL,creator_user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,title VARCHAR(160) NOT NULL,target_members INT UNSIGNED NOT NULL DEFAULT 2,current_members INT UNSIGNED NOT NULL DEFAULT 0,max_members INT UNSIGNED NOT NULL DEFAULT 0,member_discount_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,leader_reward_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,discount_percent_snapshot INT UNSIGNED NOT NULL DEFAULT 0,reservation_minutes INT UNSIGNED NOT NULL DEFAULT 15,reserved_members INT UNSIGNED NOT NULL DEFAULT 0,flow_version TINYINT UNSIGNED NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'draft',starts_at DATETIME NULL,expires_at DATETIME NULL,successful_at DATETIME NULL,failed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_group_campaign_creator(creator_user_id,status,created_at),KEY idx_group_campaign_status(status,starts_at,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS group_campaign_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,product_plan_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uk_group_campaign_plan(campaign_id,product_plan_id),KEY idx_group_campaign_plan_campaign(campaign_id),KEY idx_group_campaign_plan_plan(product_plan_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
