CREATE TABLE IF NOT EXISTS leader_rewards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,leader_user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,coupon_id BIGINT UNSIGNED NULL,reward_cents BIGINT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'pending',idempotency_key VARCHAR(100) NULL UNIQUE,awarded_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uk_leader_reward_campaign(campaign_id,leader_user_id),KEY idx_leader_reward_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
